schema.content:
Table "Dorm" {
  "dormid" INTEGER
  "dorm_name" TEXT
  "student_capacity" INTEGER
  "gender" TEXT
}

Table "Dorm_amenity" {
  "amenid" INTEGER
  "amenity_name" TEXT
}

Table "Has_amenity" {
  "dormid" INTEGER
  "amenid" INTEGER
}

Table "Lives_in" {
  "stuid" INTEGER
  "dormid" INTEGER
  "room_number" INTEGER
}

Table "Student" {
  "StuID" INTEGER [pk]
  "LName" TEXT
  "Fname" TEXT
  "Age" INTEGER
  "Sex" TEXT
  "Major" INTEGER
  "Advisor" INTEGER
  "city_code" TEXT
}



Ref: "Has_amenity"."amenid" > "Dorm_amenity"."amenid"

Ref: "Has_amenity"."dormid" > "Dorm"."dormid"

Ref: "Lives_in"."dormid" > "Dorm"."dormid"

Ref: "Lives_in"."stuid" > "Student"."StuID"
